functionsSource.Hisense_RegisterAppMessageListener:
function(eventType, callback) {
    console.log("registerAppMessageListeners");
    registeredEvent.push(eventType);

    function cb_CCMode(value) {
        var obj = {};
        obj.from = "browser";
        obj.event = "statemode";
        obj.data = {};
        switch(value) {
        case 0:
        default:
            obj.data.msgVal="off";
            break;
        case 1:
            obj.data.msgVal="on";
            break;
        case 2:
            obj.data.msgVal="onWhenMute";
            break;
        }

        return callback(obj);
    }

    function cb_CCStyle(value) {
        var obj = {};
        obj.from = "browser";
        obj.data = JSON.parse(value);
        obj.event = "subtitleStyle";
        return callback(obj);
    }

    function cb_Mute(value) {
        var obj = {};
        obj.from = "browser";
        obj.event = "mute";
        obj.data = {};
        if(value != null || value != undefined) {
            obj.data.msgVal = value;
        }
        return callback(obj);
    }

    if(registeredEvent.join().indexOf("subtitleStyle") != -1) {
        Hisense_RegisterObserver("CCStyle", cb_CCStyle);
    }

    if(registeredEvent.join().indexOf("statemode") != -1) {
        Hisense_RegisterObserver("CCModeStatus", cb_CCMode);
    }

    if(registeredEvent.join().indexOf("mute") != -1) {
        Hisense_RegisterObserver("soundMute", cb_Mute);
    }

    playEventListener = function playEventListener(data) {
        var msg = null;
        try {
            msg = JSON.parse(data);
        } catch(e) {
            console.log("Error: "+e);
        }

        if(registeredEvent.join().indexOf(msg.event) != -1) {
            callback(msg);
        } else {
            console.log("invalid event type");
            return;
        }
    }

    if(!!omi_platform) {
        omi_platform.addPlatformEventListener(playEventListener);
    }
}

